func (q *Queries) UpdateCardText(ctx context.Context, arg UpdateCardTextParams) (Card, error) {
	row := q.db.QueryRow(ctx, updateCardText,
		arg.Title,
		arg.Description,
		arg.WorkspaceID,
		arg.ID,
	)
	var i Card
	err := row.Scan(
		&i.ID,
		&i.WorkspaceID,
		&i.ProjectID,
		&i.Kind,
		&i.Title,
		&i.Description,
		&i.DiscussionState,
		&i.TodoState,
		&i.OngoingState,
		&i.SourceDiscussionID,
		&i.RequiredConfirmations,
		&i.CreatedBySourceID,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.CreateIdempotencyKey,
		&i.CreateRequestHash,
	)
	return i, err
}

const updateProject = `-- name: UpdateProject :one
UPDATE projects
SET name = $1,
    description = $2,
    instructions = $3,
    updated_at = now()
WHERE workspace_id = $4
  AND id = $5
RETURNING id, workspace_id, name, description, instructions, created_at, updated_at
`

type UpdateProjectParams struct {
	Name         string    `json:"name"`
	Description  string    `json:"description"`
	Instructions string    `json:"instructions"`
	WorkspaceID  uuid.UUID `json:"workspace_id"`
	ID           uuid.UUID `json:"id"`
}

func (q *Queries) UpdateProject(ctx context.Context, arg UpdateProjectParams) (Project, error) {
	row := q.db.QueryRow(ctx, updateProject,
		arg.Name,
		arg.Description,
		arg.Instructions,
		arg.WorkspaceID,
		arg.ID,
	)
	var i Project
	err := row.Scan(
		&i.ID,
		&i.WorkspaceID,
		&i.Name,
		&i.Description,
		&i.Instructions,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
